// Extract text from PDF binary data using basic text extraction
// n8n has the PDF binary in $input.item.binary.data
const items = $input.all();
const item = items[0];

const documentId = $('Webhook').first().json.body.documentId;
const filename = $('Webhook').first().json.body.filename;

// Get binary PDF data
const binaryData = item.binary?.data;
if (!binaryData) {
  throw new Error('No binary data received from PDF download');
}

// Convert binary to buffer and extract text
// n8n Code node can access Buffer
const buffer = Buffer.from(binaryData.data, 'base64');

// Simple PDF text extraction - look for text between BT...ET markers
let text = '';
const pdfString = buffer.toString('latin1');

// Extract readable text using regex patterns for PDF streams
const streamMatches = pdfString.match(/stream[\s\S]*?endstream/g) || [];
for (const stream of streamMatches) {
  // Look for text operators Tj, TJ, '
  const textMatches = stream.match(/\(([^)]+)\)\s*Tj/g) || [];
  for (const match of textMatches) {
    const extracted = match.replace(/\(([^)]+)\)\s*Tj/, '$1');
    text += extracted + ' ';
  }

  // Also look for TJ arrays
  const tjMatches = stream.match(/\[([^\]]+)\]\s*TJ/g) || [];
  for (const match of tjMatches) {
    const parts = match.match(/\(([^)]+)\)/g) || [];
    for (const part of parts) {
      text += part.replace(/[()]/g, '') + ' ';
    }
  }
}

// Fallback: extract any readable ASCII text from the PDF
if (text.trim().length < 100) {
  const asciiMatches = pdfString.match(/[\x20-\x7E]{4,}/g) || [];
  text = asciiMatches
    .filter(s => !/^\/[A-Za-z]/.test(s)) // skip PDF operators
    .filter(s => !/(endobj|endstream|xref|trailer|startxref|%%EOF)/.test(s))
    .join(' ');
}

if (!text || text.trim().length < 10) {
  throw new Error(`Could not extract text from PDF: ${filename}. The PDF may be image-based or encrypted.`);
}

return [{
  json: {
    documentId,
    filename,
    text: text.trim(),
    charCount: text.length
  }
}];

// Split text into overlapping chunks
const item = $input.first();
const { documentId, filename, text } = item.json;

const CHUNK_SIZE = 800;
const CHUNK_OVERLAP = 200;

const chunks = [];
let start = 0;
let chunkIndex = 0;

while (start < text.length) {
  const end = Math.min(start + CHUNK_SIZE, text.length);
  let chunk = text.slice(start, end);

  // Try to split at sentence boundary
  if (end < text.length) {
    const lastPeriod = chunk.lastIndexOf('. ');
    const lastNewline = chunk.lastIndexOf('\n');
    const splitAt = Math.max(lastPeriod, lastNewline);
    if (splitAt > CHUNK_SIZE * 0.5) {
      chunk = text.slice(start, start + splitAt + 1);
    }
  }

  chunks.push({
    json: {
      documentId,
      filename,
      chunkIndex,
      content: chunk.trim(),
      totalChunks: 0 // will be updated
    }
  });

  chunkIndex++;
  start = end - CHUNK_OVERLAP;
  if (start >= text.length) break;
}

// Update totalChunks
for (const chunk of chunks) {
  chunk.json.totalChunks = chunks.length;
}

return chunks;

// Prepare Pinecone upsert payload
const embeddingResponse = $input.first().json;
const chunkData = $('Split Chunks').item.json;

const vector = embeddingResponse.data?.[0]?.embedding;
if (!vector || !Array.isArray(vector)) {
  throw new Error('No embedding returned from OpenRouter: ' + JSON.stringify(embeddingResponse));
}

const vectorId = `${chunkData.documentId}_chunk_${chunkData.chunkIndex}`;

return [{
  json: {
    vectors: [{
      id: vectorId,
      values: vector,
      metadata: {
        documentId: chunkData.documentId,
        filename: chunkData.filename,
        chunkIndex: chunkData.chunkIndex,
        content: chunkData.content.substring(0, 1000), // Pinecone metadata limit
        pageEstimate: Math.floor(chunkData.chunkIndex / 3) + 1
      }
    }],
    documentId: chunkData.documentId,
    totalChunks: chunkData.totalChunks,
    chunkIndex: chunkData.chunkIndex
  }
}];

// After all chunks are processed, check if this is the last chunk
// and update document status in PostgreSQL
const chunkData = $('Prepare Vector').item.json;

return [{
  json: {
    documentId: chunkData.documentId,
    chunkIndex: chunkData.chunkIndex,
    totalChunks: chunkData.totalChunks,
    isLastChunk: chunkData.chunkIndex === chunkData.totalChunks - 1
  }
}];
